    }

    /// Spawn a command without shelling out to an external shell
    pub fn spawn_simple_command(&self, cwd: &str) -> Result<std::process::Command, ShellError> {
        let (head, _, _) = trim_enclosing_quotes(&self.name.item);
        let head = nu_path::expand_tilde(head);
        let mut expanded_head = PathBuf::with_capacity(head.as_os_str().len());
        for component in nu_path::components(&head) {
            if let std::path::Component::Normal(part) = component {
                let bytes = part.as_encoded_bytes();
                if bytes.len() >= 3 && bytes.iter().all(|byte| *byte == b'.') {
                    for _ in 0..bytes.len() - 1 {
                        expanded_head.push("..");
                    }
                    continue;
                }
            }
            expanded_head.push(component);
        }
        let head = expanded_head.to_string_lossy().to_string();

        let mut process = std::process::Command::new(head);
        let cwd_path = PathBuf::from(cwd);

        for (arg, arg_keep_raw) in self.args.iter().zip(self.arg_keep_raw.iter()) {
            let (trimmed_args, mut run_glob_expansion, mut keep_raw) =
                trim_enclosing_quotes(&arg.item);
            if *arg_keep_raw {
                keep_raw = true;
                run_glob_expansion = false;
            }

            let mut prepared = Spanned {
                item: if keep_raw {
                    trimmed_args
                } else {
                    remove_quotes(trimmed_args)
                },
                span: arg.span,
            };

            if !keep_raw {
                prepared.item = nu_path::expand_tilde(prepared.item)
                    .to_string_lossy()
                    .to_string();
            }

            let should_expand_glob = prepared.item.contains('*') && run_glob_expansion;
            if !should_expand_glob {
                process.arg(&prepared.item);
                continue;
            }

            let glob_path = Spanned {
                item: NuGlob::Expand(prepared.item.clone()),
                span: prepared.span,
            };
            let Ok((prefix, matches)) =
                nu_engine::glob_from(&glob_path, &cwd_path, prepared.span, None)
            else {
                continue;
            };
            let matches: Vec<_> = matches.collect();
            if matches.is_empty() {
                process.arg(&prepared.item);
            }
            for matched in matches {
                if let Ok(path) = matched {
                    if let Some((prefix, remainder)) = prefix.as_ref().and_then(|prefix| {
                        path.strip_prefix(prefix)
                            .ok()
                            .map(|remainder| (prefix, remainder))
